<?php
namespace app\controller;use app\BaseController;use app\service\AlipayService;use app\service\PaymentGuard;use app\service\QuotaLotService;use think\facade\Db;use think\facade\Session;use think\facade\View;
class Recharge extends BaseController{
 private function uid():int{return(int)Session::get('lumen_user_id');} private function guard(){return$this->uid()?null:redirect('/user/login');}
 private function sig(array $u):string{$secret=trim((string)@file_get_contents((string)(getenv('LUMEN_INTEGRITY_KEY_FILE')?:'/www/server/lumenapi/integrity.key')));return hash_hmac('sha256',$u['id'].'|'.($u['quota_total']===null?'NULL':$u['quota_total']).'|'.$u['quota_used'],$secret);}
 private function validQuotaSignature(array $u):bool{return !empty($u['quota_integrity_hash'])&&hash_equals((string)$u['quota_integrity_hash'],$this->sig($u));}
 public function index(){if($r=$this->guard())return$r;Db::name('recharge_orders')->where('user_id',$this->uid())->where('status','pending')->whereNotNull('expired_at')->where('expired_at','<',date('Y-m-d H:i:s'))->update(['status'=>'expired','updated_at'=>date('Y-m-d H:i:s')]);$u=Db::name('users')->where('id',$this->uid())->find();$orders=Db::name('recharge_orders')->where('user_id',$this->uid())->order('id','desc')->limit(30)->select()->toArray();foreach($orders as &$o){$lot=Db::name('quota_lots')->where('source_type','recharge')->where('source_id',$o['id'])->find();$o['paid_remaining']=(int)($lot['paid_remaining']??0);$o['bonus_remaining']=(int)($lot['bonus_remaining']??0);$o['refundable_cents']=$lot&&$lot['paid_quota']?min(max(0,(int)$o['amount_cents']-(int)$o['refund_amount_cents']),intdiv((int)$lot['paid_amount_cents']*(int)$lot['paid_remaining'],(int)$lot['paid_quota'])):0;$o['refund_request']=Db::name('refund_orders')->where('recharge_order_id',$o['id'])->whereIn('status',['requested','approved','provider_processing','needs_reconcile'])->order('id','desc')->find();}unset($o);$refunds=Db::name('refund_orders')->where('user_id',$this->uid())->where('request_source','user')->order('id','desc')->limit(30)->select()->toArray();View::assign(['user'=>$u,'orders'=>$orders,'refunds'=>$refunds,'ready'=>AlipayService::ready()]);return View::fetch(root_path().'view/user/recharge.html');}
 public function create(){if($r=$this->guard())return$r;$account=Db::name('users')->where('id',$this->uid())->find();if(!$account||!(int)$account['status']||!empty($account['integrity_locked']))return response('账户当前处于安全限制状态，暂不能创建充值订单',403);if(!PaymentGuard::allow($this->uid(),'create',5,60))return response('操作过于频繁，请稍后再试',429);if(!AlipayService::ready())return response('充值通道尚未配置完成',503);$yuan=trim((string)input('post.amount',''));if(!preg_match('/^\d+(\.\d{1,2})?$/',$yuan))return response('充值金额格式不正确',422);[$whole,$frac]=array_pad(explode('.',$yuan,2),2,'');$cents=((int)$whole*100)+(int)str_pad($frac,2,'0');if($cents<100||$cents>10000000)return response('单笔充值金额范围 1-100000 元',422);$rate=max(1,(int)(Db::name('settings')->where('key','recharge.quota_per_yuan')->value('value')??100));$quota=intdiv($cents*$rate,100);$bonusEnabled=(string)(Db::name('settings')->where('key','recharge.bonus_enabled')->value('value')??'0')==='1';$bonusPercent=max(0,min(10000,(int)(Db::name('settings')->where('key','recharge.bonus_percent')->value('value')??100)));$bonus=$bonusEnabled?intdiv($quota*$bonusPercent,100):0;$no='LM'.date('YmdHis').strtoupper(bin2hex(random_bytes(5)));$now=date('Y-m-d H:i:s');$id=Db::name('recharge_orders')->insertGetId(['order_no'=>$no,'user_id'=>$this->uid(),'provider'=>'alipay','amount_cents'=>$cents,'quota_amount'=>$quota,'bonus_quota'=>$bonus,'status'=>'pending','expired_at'=>date('Y-m-d H:i:s',time()+1800),'created_at'=>$now,'updated_at'=>$now]);$order=Db::name('recharge_orders')->where('id',$id)->find();return redirect(AlipayService::pagePayUrl($order));}
 public function notify(){$p=request()->post();$hash=hash('sha256',json_encode($p,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));$no=(string)($p['out_trade_no']??'');$trade=(string)($p['trade_no']??'');$state=(string)($p['trade_status']??'');$verified=$p&&AlipayService::verifyNotify($p);$order=$no!==''?Db::name('recharge_orders')->where('order_no',$no)->find():null;Db::name('payment_events')->insert(['order_id'=>$order['id']??null,'order_no'=>$no?:null,'provider'=>'alipay','provider_trade_no'=>$trade?:null,'event_type'=>$verified?'notify':'notify_rejected','trade_status'=>$state?:null,'verified'=>$verified?1:0,'payload_hash'=>$hash,'detail'=>$verified?'verified':'signature_invalid','created_at'=>date('Y-m-d H:i:s')]);if(!$verified)return response('failure',400);if(!$order)return response('failure',404);Db::name('recharge_orders')->where('id',$order['id'])->update(['last_notify_at'=>date('Y-m-d H:i:s'),'updated_at'=>date('Y-m-d H:i:s')]);if(!in_array($state,['TRADE_SUCCESS','TRADE_FINISHED'],true))return response('success',200);if($trade===''){Db::name('recharge_orders')->where('id',$order['id'])->update(['failure_reason'=>'trade_no_empty','updated_at'=>date('Y-m-d H:i:s')]);Db::name('payment_events')->insert(['order_id'=>$order['id'],'order_no'=>$no,'provider'=>'alipay','provider_trade_no'=>null,'event_type'=>'credit_failed','trade_status'=>$state,'verified'=>1,'payload_hash'=>$hash,'detail'=>'trade_no_empty','created_at'=>date('Y-m-d H:i:s')]);return response('failure',400);}try{Db::transaction(function()use($p,$no,$trade,$hash){$o=Db::name('recharge_orders')->where('order_no',$no)->lock(true)->find();if(!$o)throw new \RuntimeException('order');if($o['status']==='credited'){if((string)$o['provider_trade_no']!==$trade)throw new \RuntimeException('credited_trade_no_mismatch');return;}if(!in_array($o['status'],['pending','paid','expired'],true))throw new \RuntimeException('order_state');$amount=(string)($p['total_amount']??'');if(!preg_match('/^\d+(?:\.\d{1,2})?$/',$amount))throw new \RuntimeException('amount_format');[$aw,$af]=array_pad(explode('.',$amount,2),2,'');$paid=((int)$aw*100)+(int)str_pad($af,2,'0');if($paid!==(int)$o['amount_cents'])throw new \RuntimeException('amount');$cfg=AlipayService::settings();if(empty($p['app_id'])||!hash_equals((string)($cfg['alipay.app_id']??''),(string)$p['app_id']))throw new \RuntimeException('app_id');if(!empty($cfg['alipay.seller_id'])&&(empty($p['seller_id'])||!hash_equals((string)$cfg['alipay.seller_id'],(string)$p['seller_id'])))throw new \RuntimeException('seller_id');$existing=Db::name('recharge_orders')->where('provider','alipay')->where('provider_trade_no',$trade)->where('id','<>',$o['id'])->find();if($existing)throw new \RuntimeException('trade_no_conflict');$u=Db::name('users')->where('id',$o['user_id'])->lock(true)->find();if(!$u)throw new \RuntimeException('user');if(!empty($u['integrity_locked']))throw new \RuntimeException('account_integrity_locked');if(!$this->validQuotaSignature($u))throw new \RuntimeException('account_integrity_invalid');$now=date('Y-m-d H:i:s');$quota=(int)$o['quota_amount'];$debt=(int)($u['penalty_debt']??0);$repay=min($debt,$quota);$credit=$quota-$repay;$bonus=(int)($o['bonus_quota']??0);$newDebt=$debt-$repay;$before=$u['quota_total']===null?null:max(0,(int)$u['quota_total']-(int)$u['quota_used']);$newTotal=$u['quota_total']===null?null:(int)$u['quota_total']+$credit+$bonus;$after=$newTotal===null?null:max(0,$newTotal-(int)$u['quota_used']);$tmp=$u;$tmp['quota_total']=$newTotal;$hashSig=$this->sig($tmp);Db::name('users')->where('id',$u['id'])->update(['quota_total'=>$newTotal,'trusted_quota_total'=>$newTotal,'trusted_quota_used'=>(int)$u['quota_used'],'penalty_debt'=>$newDebt,'quota_integrity_hash'=>$hashSig,'updated_at'=>$now]);Db::name('keys')->where('user_id',$u['id'])->update(['quota_total'=>$newTotal,'quota_used'=>(int)$u['quota_used'],'updated_at'=>$now]);if($repay>0)Db::name('quota_ledger')->insert(['user_id'=>$u['id'],'direction'=>'out','amount'=>$repay,'source_type'=>'penalty_repayment','source_id'=>$o['id'],'request_id'=>$o['order_no'].'-penalty','balance_before'=>$before,'balance_after'=>$before,'remark'=>'充值优先抵扣处罚欠额','created_at'=>$now]);if($credit>0)Db::name('quota_ledger')->insert(['user_id'=>$u['id'],'direction'=>'in','amount'=>$credit,'source_type'=>'recharge','source_id'=>$o['id'],'request_id'=>$o['order_no'].'-recharge','balance_before'=>$before,'balance_after'=>$after,'remark'=>'支付宝充值到账','created_at'=>$now]);if($bonus>0)Db::name('quota_ledger')->insert(['user_id'=>$u['id'],'direction'=>'in','amount'=>$bonus,'source_type'=>'recharge_bonus','source_id'=>$o['id'],'request_id'=>$o['order_no'].'-bonus','balance_before'=>$before,'balance_after'=>$after,'remark'=>'充值活动赠送额度（不可现金退款，退款时回收）','created_at'=>$now]);$refundableCents=$quota>0?intdiv((int)$o['amount_cents']*$credit,$quota):0;QuotaLotService::createRechargeLot($o,$credit,$bonus,$refundableCents);Db::name('recharge_orders')->where('id',$o['id'])->update(['status'=>'credited','provider_trade_no'=>$trade,'paid_at'=>$now,'credited_at'=>$now,'notify_payload_hash'=>$hash,'failure_reason'=>null,'updated_at'=>$now]);});}catch(\Throwable $e){Db::name('recharge_orders')->where('order_no',$no)->update(['failure_reason'=>mb_substr($e->getMessage(),0,255),'updated_at'=>date('Y-m-d H:i:s')]);Db::name('payment_events')->insert(['order_id'=>$order['id'],'order_no'=>$no,'provider'=>'alipay','provider_trade_no'=>$trade?:null,'event_type'=>'credit_failed','trade_status'=>$state,'verified'=>1,'payload_hash'=>$hash,'detail'=>mb_substr($e->getMessage(),0,500),'created_at'=>date('Y-m-d H:i:s')]);return response('failure',500);}return response('success',200);}

 public function queryOrder($id){if($r=$this->guard())return$r;if(!PaymentGuard::allow($this->uid(),'query',10,60))return response('查询过于频繁，请稍后再试',429);$o=Db::name('recharge_orders')->where('id',(int)$id)->where('user_id',$this->uid())->find();if(!$o)return response('Not Found',404);if($o['status']==='credited')return redirect('/user/recharge');try{$raw=AlipayService::query($o['order_no']);$resp=$raw['alipay_trade_query_response']??[];$code=(string)($resp['code']??'');$tradeStatus=(string)($resp['trade_status']??'');Db::name('payment_events')->insert(['order_id'=>$o['id'],'order_no'=>$o['order_no'],'provider'=>'alipay','provider_trade_no'=>$resp['trade_no']??null,'event_type'=>'manual_query','trade_status'=>$tradeStatus?:null,'verified'=>1,'payload_hash'=>hash('sha256',json_encode($raw,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)),'detail'=>'signature_verified;code='.$code,'created_at'=>date('Y-m-d H:i:s')]);if($code!=='10000')return redirect('/user/recharge?query=not_found');return redirect('/user/recharge?query='.urlencode($tradeStatus?:'unknown'));}catch(\Throwable $e){return redirect('/user/recharge?query=failed');}}

 public function returned(){if($r=$this->guard())return$r;return redirect('/user/recharge');}
}
